// Inject fake SaaS top nav logo + CTA
(function() {
  const nav = document.createElement('div');
  nav.id = 'saas-topnav';
  nav.style.cssText = `
    position: fixed; top: 0; left: 0; right: 0; height: 64px;
    display: flex; align-items: center; justify-content: space-between;
    padding: 0 40px; z-index: 102; pointer-events: none;
    font-family: 'Inter', sans-serif;
  `;
  nav.innerHTML = `
    <span style="font-family:'Plus Jakarta Sans',sans-serif;font-weight:800;font-size:17px;color:#0d0f1a;letter-spacing:-0.02em;pointer-events:auto;">
      port<span style="color:#4f46e5;">folio</span><span style="font-size:10px;font-weight:600;background:#4f46e5;color:#fff;border-radius:4px;padding:2px 6px;margin-left:6px;letter-spacing:0.05em;vertical-align:middle;">AI</span>
    </span>
    <span style="pointer-events:auto;display:flex;gap:8px;align-items:center;">
      <button style="background:none;border:1px solid #e2e5ee;border-radius:7px;padding:8px 16px;font-size:13px;font-weight:500;color:#5b6278;cursor:pointer;font-family:inherit;">Log in</button>
      <button style="background:linear-gradient(135deg,#4f46e5,#7c3aed);border:none;border-radius:7px;padding:9px 18px;font-size:13px;font-weight:600;color:#fff;cursor:pointer;font-family:inherit;box-shadow:0 4px 12px rgba(79,70,229,0.35);">Get started free →</button>
    </span>
  `;
  document.body.appendChild(nav);

  // Scroll-based nav shadow
  const onScroll = () => {
    const shadow = window.scrollY > 10 ? '0 1px 20px rgba(0,0,0,0.07)' : 'none';
    const pseudo = document.querySelector('.page');
    if (pseudo) pseudo.style.setProperty('--nav-shadow', shadow);
  };
  window.addEventListener('scroll', onScroll, { passive: true });

  // Animate work items on scroll
  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry, i) => {
      if (entry.isIntersecting) {
        entry.target.style.transition = `opacity 0.5s ease ${i * 0.08}s, transform 0.5s ease ${i * 0.08}s`;
        entry.target.style.opacity = '1';
        entry.target.style.transform = 'translateY(0)';
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.1 });

  document.querySelectorAll('.work-item').forEach(el => {
    el.style.opacity = '0';
    el.style.transform = 'translateY(24px)';
    observer.observe(el);
  });

  // Add a subtle animated gradient glow to hero
  const heroBefore = document.querySelector('.intro');
  if (heroBefore) {
    const glowEl = document.createElement('div');
    glowEl.style.cssText = `
      position:absolute;top:0;left:0;right:0;bottom:0;pointer-events:none;
      background:radial-gradient(ellipse at 50% 0%, rgba(79,70,229,0.06) 0%, transparent 60%);
      transition:opacity 1s ease;z-index:0;
    `;
    heroBefore.style.position = 'relative';
    heroBefore.insertBefore(glowEl, heroBefore.firstChild);
  }

  // Add "Live demo" pulse badge near contact trigger
  const trigger = document.querySelector('.contact-trigger');
  if (trigger) {
    const badge = document.createElement('span');
    badge.textContent = '● Live demo';
    badge.style.cssText = `
      font-size:12px;font-weight:600;color:#10b981;
      animation:pulse 2s ease-in-out infinite;
      font-family:'Inter',sans-serif;
    `;
    const style = document.createElement('style');
    style.textContent = `@keyframes pulse { 0%,100%{opacity:1} 50%{opacity:0.5} }`;
    document.head.appendChild(style);
    trigger.parentNode && trigger.parentNode.insertBefore(badge, trigger.nextSibling);
  }

  window.__aiCleanup = window.__aiCleanup || [];
  window.__aiCleanup.push(() => {
    nav.remove();
    window.removeEventListener('scroll', onScroll);
    observer.disconnect();
  });
})();
